# (scripts/update-tap.sh): edit the generator there, not this file.
# acs-version: 0.19.1
#
# acs releases are signed; SHA256SUMS.sig is checked against this key:
#   ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAILbxQW5C9X7CdwcQ4bab0gsQi4Evk2xfgmI/972dlHCb acs release signing
# Verify a release by hand:
#   printf 'releases@acs namespaces="acs-release" %s\n' "$key" > allowed
#   ssh-keygen -Y verify -f allowed -I releases@acs -n acs-release -s SHA256SUMS.sig < SHA256SUMS
class Acs < Formula
  desc "Persistent, reconnecting remote shells over ssh"
  homepage "https://github.com/michel-onstein/acs"
  license "MIT"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/michel-onstein/acs/releases/download/0.19.1/acs-0.19.1-aarch64-apple-darwin.tar.gz"
      sha256 "06c71234f5ab24b0a71fcc4ce6922e05e504aad840dbe8e78575a9882e269127"
    end

    on_intel do
      url "https://github.com/michel-onstein/acs/releases/download/0.19.1/acs-0.19.1-x86_64-apple-darwin.tar.gz"
      sha256 "58226926db10d99ba88475fac234aafe2b5b98b24d62472523f290269542e9fb"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/michel-onstein/acs/releases/download/0.19.1/acs-0.19.1-aarch64-unknown-linux-musl.tar.gz"
      sha256 "83dd9b71322deed9cf032e2684721c887e747ffdc3dc9c9250c9ce9cc1e6e6e3"
    end

    on_intel do
      url "https://github.com/michel-onstein/acs/releases/download/0.19.1/acs-0.19.1-x86_64-unknown-linux-musl.tar.gz"
      sha256 "d15e39c9c2dee6ee333e63de3ee6070cbe6bc710d90e88ef19f4e388cc37aa4d"
    end
  end

  def install
    bin.install "acs"
    bin.install_symlink "acs" => "acscp"
  end

  test do
    out = shell_output("#{bin}/acs --version")
    assert_match "acs #{version} ", out
    remotes = out[/^installs remotes: (.*)$/, 1].to_s.split(", ")
    assert_includes remotes, "x86_64-unknown-linux-musl"
    assert_includes remotes, "aarch64-unknown-linux-musl"
    assert_match "acs #{version} ", shell_output("#{bin}/acscp --version")
  end
end
